    {
      "card_ids": ["C30"],
      "claim": "A high-transferability record reports 28% oral bioavailability in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ursodeoxycholic acid, a carboxylic acid-containing steroid, showed 50% systemic availability in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Meperidine absolute oral bioavailability was 47-73% in healthy men, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sodium oxybate absolute oral bioavailability was about 27% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Eplerenone oral bioavailability was approximately 98% in humans, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lefamulin absolute oral bioavailability was 25.8% in fasted healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Lefamulin oral bioavailability was 19% in fed subjects, a single sub-threshold value, but fasted and absolute values for the same drug are above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental evidence overwhelmingly supports F >= 20%: direct oral bioavailability values across diverse carboxylic-acid and lipophilic scaffolds range from about 25% to 99%, with only one fed-state lefamulin value at 19%. The query's lipophilic carboxylic acid and bicyclic ether features align with these absorbable compounds, so high oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct bioavailability measurement for the exact query scaffold was retrieved; reliance on transferable analogs introduces structural uncertainty.",
    "Some records have unspecified bioavailability report types or inconsistent SMILES-record associations (e.g., C30).",
    "Fed/fasted and disease-state effects on first-pass metabolism are not fully represented."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

